CREATE TABLE user_access_projection(user_id uuid PRIMARY KEY,actor_type text NOT NULL,status text NOT NULL,token_version integer NOT NULL CHECK(token_version>=0),source_version bigint NOT NULL DEFAULT 1,applied_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE patient_access_projection(patient_id uuid PRIMARY KEY,owner_user_id uuid NOT NULL,active boolean NOT NULL,policy_version bigint NOT NULL CHECK(policy_version>0),applied_at timestamptz NOT NULL DEFAULT now());
-- Appointment-owned snapshot import boundary; no foreign database reads.
CREATE TABLE ticket_projection(ticket_id uuid PRIMARY KEY,appointment_id uuid NOT NULL,patient_id uuid NOT NULL,doctor_id uuid NOT NULL,doctor_user_id uuid NOT NULL,department_id uuid NOT NULL,ticket_type text NOT NULL CHECK(ticket_type IN ('FIRST','RETURN')),state text NOT NULL CHECK(state IN ('WAITING','CALLED','CLAIMED','NO_SHOW','DONE')),version integer NOT NULL CHECK(version>0),visit_id uuid,applied_at timestamptz NOT NULL DEFAULT now(),CHECK((ticket_type='FIRST' AND visit_id IS NULL) OR (ticket_type='RETURN' AND visit_id IS NOT NULL)));
CREATE TABLE visits(id uuid PRIMARY KEY,appointment_id uuid NOT NULL UNIQUE,patient_id uuid NOT NULL,doctor_user_id uuid NOT NULL,department_id uuid NOT NULL,claim_id uuid NOT NULL UNIQUE,state text NOT NULL CHECK(state IN ('IN_PROGRESS','LAB_REQUEST_PENDING','WAITING_LAB','RETURN_READY','WAITING_RETURN','SIGNED')),version integer NOT NULL DEFAULT 1 CHECK(version>0),return_round integer NOT NULL DEFAULT 0 CHECK(return_round IN (0,1)),started_at timestamptz NOT NULL,signed_at timestamptz,CHECK((state='SIGNED')=(signed_at IS NOT NULL)));
CREATE INDEX visits_doctor_started ON visits(doctor_user_id,started_at DESC,id);
CREATE TABLE visit_notes(id uuid PRIMARY KEY,visit_id uuid NOT NULL REFERENCES visits(id),revision integer NOT NULL CHECK(revision>0),symptoms text NOT NULL,findings text NOT NULL,assessment text NOT NULL,diagnosis text NOT NULL,author_user_id uuid NOT NULL,saved_at timestamptz NOT NULL,UNIQUE(visit_id,revision));
CREATE TABLE start_requests(request_id uuid PRIMARY KEY,ticket_id uuid NOT NULL,doctor_user_id uuid NOT NULL,ticket_snapshot jsonb NOT NULL,state text NOT NULL CHECK(state IN ('PENDING','ACCEPTED','REJECTED')),visit_id uuid REFERENCES visits(id),claim_id uuid,claim_hash text NOT NULL DEFAULT '',reason_code text NOT NULL DEFAULT '',created_at timestamptz NOT NULL,CHECK(state<>'ACCEPTED' OR (visit_id IS NOT NULL AND claim_id IS NOT NULL)));
CREATE INDEX start_requests_doctor ON start_requests(doctor_user_id,created_at DESC);
CREATE TABLE idempotency_records(actor_id uuid NOT NULL,operation text NOT NULL,idempotency_key uuid NOT NULL,request_hash text NOT NULL,response jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(actor_id,operation,idempotency_key));
CREATE TABLE outbox(message_id uuid PRIMARY KEY,aggregate_id uuid NOT NULL,destination text NOT NULL,routing_key text NOT NULL,envelope jsonb NOT NULL,status text NOT NULL DEFAULT 'PENDING' CHECK(status IN ('PENDING','SENT')),created_at timestamptz NOT NULL DEFAULT now(),sent_at timestamptz);
CREATE INDEX outbox_pending ON outbox(created_at,message_id) WHERE status='PENDING';
CREATE TABLE inbox(message_id uuid PRIMARY KEY,payload_hash text NOT NULL,status text NOT NULL DEFAULT 'PROCESSED' CHECK(status IN ('PROCESSED','RETRY_SCHEDULED','DEAD')),processed_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE retry_jobs(message_id uuid PRIMARY KEY,exchange_name text NOT NULL,routing_key text NOT NULL,body bytea NOT NULL,payload_hash text NOT NULL,attempt integer NOT NULL CHECK(attempt BETWEEN 1 AND 3),due_at timestamptz NOT NULL,status text NOT NULL DEFAULT 'PENDING' CHECK(status IN ('PENDING','PROCESSED','DEAD')),lease_id uuid,lease_until timestamptz);
CREATE INDEX retry_jobs_due ON retry_jobs(due_at) WHERE status='PENDING';
CREATE TABLE dead_letters(id uuid PRIMARY KEY,message_id text NOT NULL,exchange_name text NOT NULL,routing_key text NOT NULL,body bytea NOT NULL,payload_hash text NOT NULL,reason_code text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(message_id,payload_hash));
